head.b:skin:
/*
-----------------------------------------------
Win95 Blogger Theme
----------------------------------------------- */

html {
  min-height: 100%;
}

body {
  min-height: 100%;
  margin: 0;
  padding: 18px 18px 46px;
  background: #008080;
  color: #111111;
  font-family: "MS Sans Serif", Tahoma, Verdana, Arial, sans-serif;
  font-size: 14px;
  line-height: 1.45;
}

a {
  color: #0000ee;
}

img {
  max-width: 100%;
  height: auto;
}

#desktop-wrapper {
  width: 100%;
  max-width: 1180px;
  margin: 0 auto;
}

#desktop-icons {
  overflow: hidden;
  margin: 0 0 16px;
}

.desktop-icon {
  float: left;
  width: 76px;
  margin: 0 18px 12px 0;
  color: #ffffff;
  text-align: center;
  text-decoration: none;
  text-shadow: 1px 1px #000000;
}

.desktop-icon img {
  display: block;
  width: 32px;
  height: 32px;
  margin: 0 auto 6px;
}

.win-window,
.widget,
.post,
.comments,
.blog-pager,
.status-panel {
  background: #c0c0c0;
  color: #111111;
  border: 2px solid;
  border-top-color: #ffffff;
  border-left-color: #ffffff;
  border-right-color: #404040;
  border-bottom-color: #404040;
  box-shadow: 1px 1px 0 #000000;
}

.win-title,
.widget h2,
.post-title,
.date-header,
.comments h4 {
  min-height: 24px;
  margin: 0;
  padding: 3px 8px 4px;
  background: #000080;
  color: #ffffff;
  font-size: 14px;
  font-weight: bold;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.win-title {
  overflow: hidden;
}

.title-text {
  float: left;
}

.window-controls {
  float: right;
}

.window-controls span {
  display: inline-block;
  width: 16px;
  height: 14px;
  margin-left: 3px;
  background: #c0c0c0;
  color: #111111;
  border: 2px solid;
  border-top-color: #ffffff;
  border-left-color: #ffffff;
  border-right-color: #404040;
  border-bottom-color: #404040;
  font-size: 10px;
  line-height: 10px;
  text-align: center;
}

.win-body,
.widget-content,
.post-body,
.comments .comments-content,
.status-panel {
  padding: 12px;
}

#site-header {
  margin-bottom: 18px;
}

#site-header .win-body {
  overflow: hidden;
}

.site-icon {
  float: left;
  width: 48px;
  height: 48px;
  margin-right: 12px;
}

.site-title {
  margin: 0;
  font-size: 38px;
  line-height: 1.05;
}

.site-description {
  margin: 6px 0 0;
  color: #333333;
}

#content-wrapper {
  overflow: hidden;
}

#main-wrapper {
  float: left;
  width: 68%;
}

#sidebar-wrapper {
  float: right;
  width: 29%;
}

.section {
  margin: 0;
}

.widget {
  margin: 0 0 18px;
  overflow: hidden;
}

.widget ul,
.widget ol {
  margin: 0;
  padding-left: 20px;
}

.widget li {
  margin-top: 6px;
}

.post {
  margin: 0 0 18px;
  overflow: hidden;
}

.post-title {
  font-size: 16px;
}

.post-title a {
  color: #ffffff;
  text-decoration: none;
}

.post-header,
.post-footer,
.byline,
.post-timestamp {
  color: #333333;
  font-size: 12px;
}

.post-body {
  margin: 12px;
  background: #ffffff;
  border: 2px inset #d0d0d0;
}

.post-body blockquote {
  margin: 12px 0;
  padding: 10px 12px;
  background: #ffffe1;
  border: 1px solid #808080;
}

.post-body pre,
.post-body code {
  font-family: "Courier New", monospace;
}

.post-body pre {
  overflow: auto;
  padding: 10px;
  background: #000000;
  color: #00ff00;
}

.post-footer {
  padding: 0 12px 12px;
}

.blog-pager {
  margin: 0 0 18px;
  padding: 10px;
  overflow: hidden;
}

.blog-pager a,
.post-footer a,
.profile-link {
  display: inline-block;
  min-height: 24px;
  padding: 2px 10px 4px;
  background: #c0c0c0;
  color: #111111;
  text-decoration: none;
  border: 2px solid;
  border-top-color: #ffffff;
  border-left-color: #ffffff;
  border-right-color: #404040;
  border-bottom-color: #404040;
}

.blog-pager a:active,
.post-footer a:active,
.profile-link:active {
  border-top-color: #404040;
  border-left-color: #404040;
  border-right-color: #ffffff;
  border-bottom-color: #ffffff;
}

.Label a {
  display: inline-block;
  margin: 0 4px 6px 0;
  padding: 1px 7px 3px;
  background: #ffffff;
  border: 1px solid #808080;
}

.status-panel {
  margin-bottom: 18px;
  font-size: 13px;
  overflow: hidden;
}

.status-panel img {
  float: left;
  width: 16px;
  height: 16px;
  margin: 2px 8px 0 0;
}

.comments {
  margin-top: 18px;
}

.comments .comments-content {
  margin: 12px;
  background: #ffffff;
  border: 2px inset #d0d0d0;
}

#taskbar {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 20;
  height: 34px;
  padding: 3px 8px;
  background: #c0c0c0;
  border-top: 2px solid #ffffff;
  box-shadow: 0 -1px 0 #808080;
  overflow: hidden;
}

.start-button {
  float: left;
  min-height: 26px;
  margin-right: 8px;
  padding: 2px 10px 3px;
  background: #c0c0c0;
  color: #111111;
  border: 2px solid;
  border-top-color: #ffffff;
  border-left-color: #ffffff;
  border-right-color: #404040;
  border-bottom-color: #404040;
  font-weight: bold;
  text-decoration: none;
}

.start-button img,
.task-button img {
  width: 16px;
  height: 16px;
  margin-right: 6px;
  vertical-align: middle;
}

.task-button {
  display: block;
  margin: 0 92px 0 92px;
  padding: 3px 8px;
  border: 2px inset #d0d0d0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.clock {
  float: right;
  width: 74px;
  padding: 3px 8px;
  border: 2px inset #d0d0d0;
  text-align: center;
}

@media screen and (max-width: 860px) {
  body {
    padding: 12px 12px 46px;
  }

  .desktop-icon {
    width: 68px;
    margin-right: 10px;
    font-size: 12px;
  }

  .site-icon {
    width: 40px;
    height: 40px;
  }

  .site-title {
    font-size: 28px;
  }

  #main-wrapper,
  #sidebar-wrapper {
    float: none;
    width: auto;
  }
}
